head.script:
// Agora.io 설정
const APP_ID = "90c1b2c3196a43ffad0da502d11dfda7"; // 실제 App ID로 변경 필요
const TOKEN = null; // 테스트용 (실제 환경에서는 토큰 서버 구축 필요)

// 전역 변수
let client;
let localVideoTrack;
let localAudioTrack;
let remoteUsers = {};
let isJoined = false;
let isMuted = false;
let isVideoOff = false;

// URL에서 project_id 파라미터 가져오기
function getProjectIdFromUrl() {
    const urlParams = new URLSearchParams(window.location.search);
    const projectId = urlParams.get('project_id');
    return projectId || 'default'; // project_id가 없으면 'default' 사용
}

// 사용자 정보
let currentUser = {
    userId: Math.floor(Math.random() * 10000).toString(),
    userName: "사용자" + Math.floor(Math.random() * 100),
    channelName: "collabee-room-" + getProjectIdFromUrl()
};

scwin.onpageload = function() {
    // HTTPS 체크
    if (location.protocol !== 'https:' && location.hostname !== 'localhost') {
        scwin.addChatMessage("시스템", "⚠️ 화상통화는 HTTPS 환경에서만 작동합니다. SSL 인증서를 설정해주세요.", false);
    }

    // 세션 생성을 위한 임시 로그인 먼저 실행
    scwin.createGuestSession().then(() => {
        // 초기 설정
        scwin.initializeVideoChat();
        scwin.initializeChatWebSocket();

        // 데이터 초기화
        dma_videoChat.set("channelName", currentUser.channelName);
        dma_videoChat.set("userId", currentUser.userId);
        dma_videoChat.set("userName", currentUser.userName);
        dma_videoChat.set("isJoined", "false");
        dma_videoChat.set("isMuted", "false");
        dma_videoChat.set("isVideoOff", "false");

        // 환영 메시지 추가
        scwin.addChatMessage("시스템", "화상통화 채팅방에 오신 것을 환영합니다!", false);
        scwin.addChatMessage("시스템", " 채널: " + currentUser.channelName, false);
        scwin.addChatMessage("시스템", " 프로젝트 ID: " + getProjectIdFromUrl(), false);
        scwin.addChatMessage("시스템", " 사용자 ID: " + currentUser.userId, false);
        scwin.addChatMessage("시스템", " 메시지 폴링: 1초마다 확인", false);


    }).catch(error => {


        // 세션 없이도 기본 기능은 작동하도록
        scwin.initializeVideoChat();
        scwin.addChatMessage("시스템", "⚠️ 세션 생성 실패. 채팅 기능이 제한될 수 있습니다.", false);
        scwin.addChatMessage("시스템", "화상통화는 여전히 사용 가능합니다.", false);
    });
};

// Agora.io 초기화
scwin.initializeVideoChat = function() {
    try {
        // AgoraRTC SDK 로드 체크
        if (typeof AgoraRTC === 'undefined') {
            scwin.addChatMessage("시스템", "❌ Agora.io SDK 로드 실패. 인터넷 연결을 확인해주세요.", false);
            return;
        }

        // AgoraRTC 클라이언트 생성
        client = AgoraRTC.createClient({
            mode: "rtc",
            codec: "vp8"
        });

        // 이벤트 리스너 등록
        client.on("user-published", scwin.handleUserPublished);
        client.on("user-unpublished", scwin.handleUserUnpublished);
        client.on("user-left", scwin.handleUserLeft);

        scwin.addChatMessage("시스템", "✅ 화상통화 시스템 초기화 완료", false);
    } catch (error) {
        scwin.addChatMessage("시스템", "❌ 화상통화 초기화 실패: " + error.message, false);
    }
};

// 임시 데모용 - joinCall 함수 수정
scwin.joinCall = async function() {
    try {
        scwin.showLoading("카메라에 접근하는 중...");

        // 브라우저의 기본 getUserMedia 사용 (Agora.io 없이)
        const stream = await navigator.mediaDevices.getUserMedia({
            video: true,
            audio: true
        });

        // 로컬 비디오 표시 - 여러 방법으로 시도
        let localVideoElement = document.getElementById("localVideo");

        // WebSquare 환경에서는 다른 방식으로 요소를 찾을 수 있음
        if (!localVideoElement) {
            localVideoElement = document.querySelector("video[id*='localVideo']");
        }
        if (!localVideoElement) {
            localVideoElement = document.querySelector(".local-video");
        }

        if (localVideoElement) {
            localVideoElement.srcObject = stream;
        } else {
            // 동적으로 비디오 요소 생성
            const container = document.querySelector(".local-video-container");
            if (container) {
                const video = document.createElement("video");
                video.id = "localVideo";
                video.className = "local-video";
                video.autoplay = true;
                video.muted = true;
                video.playsInline = true;
                video.srcObject = stream;
                container.appendChild(video);
            }
        }

        isJoined = true;
        dma_videoChat.set("isJoined", "true");

        scwin.updateControlButtons();
        scwin.hideLoading();

        scwin.addChatMessage("시스템", "✅ 로컬 카메라 연결 성공! (데모 모드)", false);
        scwin.addChatMessage("시스템", "실제 화상통화를 위해서는 Agora.io APP_ID가 필요합니다.", false);


    } catch (error) {
        scwin.hideLoading();

        // 더 자세한 오류 메시지
        let errorMessage = "카메라 접근 권한이 필요합니다";
        if (error.name === 'NotAllowedError') {
            errorMessage = "카메라/마이크 권한을 허용해주세요. 주소창 왼쪽의 자물쇠 아이콘을 클릭하여 권한을 변경할 수 있습니다.";
        } else if (error.name === 'NotFoundError') {
            errorMessage = "카메라나 마이크를 찾을 수 없습니다.";
        } else if (error.name === 'NotReadableError') {
            errorMessage = "카메라가 다른 앱에서 사용 중입니다.";
        }

        scwin.showError(errorMessage);
        scwin.addChatMessage("시스템", "❌ " + errorMessage, false);
    }
};

// 화상통화 종료
scwin.leaveCall = async function() {
    try {
        scwin.showLoading("화상통화를 종료하는 중...");

        // 로컬 트랙 정리
        if (localVideoTrack) {
            localVideoTrack.stop();
            localVideoTrack.close();
            localVideoTrack = null;
        }

        if (localAudioTrack) {
            localAudioTrack.stop();
            localAudioTrack.close();
            localAudioTrack = null;
        }

        // 원격 사용자 정리
        Object.keys(remoteUsers).forEach(userId => {
            scwin.removeRemoteUser(userId);
        });

        // 채널 나가기
        await client.leave();

        isJoined = false;
        dma_videoChat.set("isJoined", "false");

        // UI 업데이트
        scwin.updateControlButtons();
        scwin.hideLoading();

        // 채팅 메시지 추가
        scwin.addChatMessage("시스템", currentUser.userName + "님이 화상통화를 종료했습니다.", false);

    } catch (error) {
        scwin.hideLoading();
        scwin.showError("화상통화 종료에 실패했습니다.");
    }
};

// 마이크 토글
scwin.toggleMute = async function() {
    try {
        if (!localAudioTrack) return;

        if (isMuted) {
            await localAudioTrack.setEnabled(true);
            isMuted = false;
            dma_videoChat.set("isMuted", "false");
        } else {
            await localAudioTrack.setEnabled(false);
            isMuted = true;
            dma_videoChat.set("isMuted", "true");
        }

        scwin.updateControlButtons();
    } catch (error) {
        scwin.showError("마이크 설정에 실패했습니다.");
    }
};

// 비디오 토글
scwin.toggleVideo = async function() {
    try {
        if (!localVideoTrack) return;

        if (isVideoOff) {
            await localVideoTrack.setEnabled(true);
            isVideoOff = false;
            dma_videoChat.set("isVideoOff", "false");
        } else {
            await localVideoTrack.setEnabled(false);
            isVideoOff = true;
            dma_videoChat.set("isVideoOff", "true");
        }

        scwin.updateControlButtons();
    } catch (error) {
        scwin.showError("비디오 설정에 실패했습니다.");
    }
};

// 원격 사용자 퍼블리시 핸들러
scwin.handleUserPublished = async function(user, mediaType) {
    try {
        await client.subscribe(user, mediaType);

        if (mediaType === "video") {
            const remoteVideoContainer = document.createElement("div");
            remoteVideoContainer.className = "remote-user-video";
            remoteVideoContainer.id = `remote-${user.uid}`;

            const videoWrapper = document.createElement("div");
            videoWrapper.className = "remote-video-wrapper";

            const videoPlayer = document.createElement("div");
            videoPlayer.className = "remote-video-player";
            videoPlayer.id = `remote-video-${user.uid}`;

            const userName = document.createElement("div");
            userName.className = "remote-user-name";
            userName.textContent = `사용자${user.uid}`;

            videoWrapper.appendChild(videoPlayer);
            videoWrapper.appendChild(userName);
            remoteVideoContainer.appendChild(videoWrapper);

            document.getElementById("remoteVideosGrid").appendChild(remoteVideoContainer);

            user.videoTrack.play(`remote-video-${user.uid}`);
        }

        if (mediaType === "audio") {
            user.audioTrack.play();
        }

        remoteUsers[user.uid] = user;
    } catch (error) {
    }
};

// 원격 사용자 언퍼블리시 핸들러
scwin.handleUserUnpublished = function(user, mediaType) {
    if (mediaType === "video") {
        const remoteVideoElement = document.getElementById(`remote-${user.uid}`);
        if (remoteVideoElement) {
            remoteVideoElement.remove();
        }
    }
};

// 원격 사용자 퇴장 핸들러
scwin.handleUserLeft = function(user) {
    scwin.removeRemoteUser(user.uid);
};

// 원격 사용자 제거
scwin.removeRemoteUser = function(userId) {
    const remoteVideoElement = document.getElementById(`remote-${userId}`);
    if (remoteVideoElement) {
        remoteVideoElement.remove();
    }
    delete remoteUsers[userId];
};

// 컨트롤 버튼 업데이트 - 안전한 접근 방식
scwin.updateControlButtons = function() {
    try {
        // 안전한 요소 접근
        const joinBtn = document.getElementById("joinBtn") || document.querySelector("[id*='joinBtn']");
        const leaveBtn = document.getElementById("leaveBtn") || document.querySelector("[id*='leaveBtn']");
        const muteBtn = document.getElementById("muteBtn") || document.querySelector("[id*='muteBtn']");
        const videoBtn = document.getElementById("videoBtn") || document.querySelector("[id*='videoBtn']");

        if (isJoined) {
            if (joinBtn && joinBtn.style) joinBtn.style.display = "none";
            if (leaveBtn && leaveBtn.style) leaveBtn.style.display = "inline-block";
            if (muteBtn) muteBtn.disabled = false;
            if (videoBtn) videoBtn.disabled = false;

            // 마이크 버튼 상태
            if (muteBtn) {
                if (isMuted) {
                    muteBtn.textContent = "MUTE";
                    muteBtn.classList.add("muted");
                } else {
                    muteBtn.textContent = "MIC";
                    muteBtn.classList.remove("muted");
                }
            }

            // 비디오 버튼 상태
            if (videoBtn) {
                if (isVideoOff) {
                    videoBtn.textContent = "CAM OFF";
                    videoBtn.classList.add("video-off");
                } else {
                    videoBtn.textContent = "CAM ON";
                    videoBtn.classList.remove("video-off");
                }
            }
        } else {
            if (joinBtn && joinBtn.style) joinBtn.style.display = "inline-block";
            if (leaveBtn && leaveBtn.style) leaveBtn.style.display = "none";
            if (muteBtn) muteBtn.disabled = true;
            if (videoBtn) videoBtn.disabled = true;
        }
    } catch (error) {
    }
};

// 게스트 세션 생성 함수
scwin.createGuestSession = async function() {
    try {

        // WebSquare 로그인 서비스를 호출해서 세션 생성
        const response = await fetch('/InsWebApp/CmmLogin.pwkjson', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                "loginVo": {
                    "id": "guest_" + currentUser.userId,
                    "pw": "guest"
                }
            })
        });

        if (response.ok) {
            scwin.addChatMessage("시스템", "✅ 게스트 세션 생성 완료", false);
            return true;
        } else {
            return true; // 로그인 실패여도 세션은 생성될 수 있음
        }
    } catch (error) {
        // 오류가 발생해도 계속 진행 (채팅 기능을 위해)
        return true;
    }
};

// 실시간 채팅 초기화
let lastMessageTimestamp = 0;
let chatPollingInterval;

// 타임스탬프 관리 함수들
function getLastMessageTimestamp() {
    const channelKey = `lastTimestamp_${currentUser.channelName}`;
    const stored = localStorage.getItem(channelKey);
    return stored ? parseInt(stored) : 0;
}

function setLastMessageTimestamp(timestamp) {
    const channelKey = `lastTimestamp_${currentUser.channelName}`;
    lastMessageTimestamp = timestamp;
    localStorage.setItem(channelKey, timestamp.toString());
}

scwin.initializeChatWebSocket = function() {
    // 저장된 타임스탬프 로드
    lastMessageTimestamp = getLastMessageTimestamp();

    // 기존 메시지 로드
    scwin.loadChatMessages();

    // 스크롤 강제 활성화 (초기화 시) - 여러 번 시도
    setTimeout(() => {
        scwin.forceScrollEnable();
    }, 500);

    setTimeout(() => {
        scwin.forceScrollEnable();
    }, 1000);

    setTimeout(() => {
        scwin.forceScrollEnable();
    }, 2000);

    // 주기적으로 새 메시지 확인 (1초마다 - 더 실시간처럼)
    chatPollingInterval = setInterval(() => {
        scwin.checkNewMessages();
    }, 1000);

    // 채팅 입력창에 포커스 설정
    setTimeout(() => {
        const chatInput = document.getElementById("chatInput");
        if (chatInput) {
            chatInput.focus();
            // JavaScript로 직접 이벤트 리스너 추가 (백업용)
            chatInput.addEventListener('keydown', function(e) {
                if (e.keyCode === 13 || e.key === 'Enter') {
                    e.preventDefault();
                    scwin.sendChatMessage();
                }
            });

            chatInput.addEventListener('keypress', function(e) {
                if (e.keyCode === 13 || e.key === 'Enter') {
                    e.preventDefault();
                    scwin.sendChatMessage();
                }
            });

        }
    }, 1000);
};

// 채팅 메시지 전송
scwin.sendChatMessage = async function() {
    const messageInput = document.getElementById("chatInput");
    const message = messageInput.value.trim();

    if (!message) return;

    try {
        // 서버로 메시지 전송 (WebSquare 방식)
        const response = await fetch('/InsWebApp/ChatSend.pwkjson', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                "chatVo": {
                    "channelName": currentUser.channelName,
                    "userId": currentUser.userId,
                    "userName": currentUser.userName,
                    "message": message
                }
            })
        });

        const result = await response.json();

        // HTTP 200이고 WebSquare 성공 응답인 경우
        if (response.ok && (!result.resCode || result.resCode === "SUCC.SVR.001" || result.resCode.startsWith("SUCC") || result.success === true)) {
            // 입력창 초기화 및 포커스 유지
            messageInput.value = "";
            messageInput.focus(); // 포커스 다시 설정

            // 짧은 지연 후 새 메시지 확인 (서버 처리 시간 고려)
            setTimeout(() => {
                scwin.checkNewMessages();
            }, 500);

        } else {
            scwin.addChatMessage("시스템", "❌ 메시지 전송 실패: " + (result.resMsg || "알 수 없는 오류"), false);
        }

    } catch (error) {
        scwin.addChatMessage("시스템", "❌ 서버 연결 오류. 메시지 전송에 실패했습니다.", false);
    }
};

// 서버에서 채팅 메시지 로드
scwin.loadChatMessages = async function() {
    try {
        const response = await fetch('/InsWebApp/ChatAll.pwkjson', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                "chatVo": {
                    "channelName": currentUser.channelName
                }
            })
        });

        const result = await response.json();

        // WebSquare 응답 처리 - 여러 가능한 구조 대응
        let messages = [];

        if (Array.isArray(result)) {
            messages = result;
        } else if (result && result.elData && Array.isArray(result.elData.chatVo)) {
            // 주요 케이스: elData.chatVo 구조
            messages = result.elData.chatVo;
        } else if (result && Array.isArray(result.chatVo)) {
            messages = result.chatVo;
        } else if (result && result.data && Array.isArray(result.data.chatVo)) {
            messages = result.data.chatVo;
        } else if (result && result.data && Array.isArray(result.data)) {
            messages = result.data;
        } else if (result && typeof result === 'object') {
            // 객체의 값들 중에서 배열 찾기
            for (const key in result) {
                if (Array.isArray(result[key])) {
                    messages = result[key];
                    break;
                }
            }
        }

        if (messages && messages.length > 0) {
            // 기존 메시지 클리어
            dlt_chatMessages.removeAll();

            // 서버에서 받은 메시지들 추가
            messages.forEach(msg => {
                const isOwn = msg.userId === currentUser.userId;
                scwin.addChatMessageToList(msg.userName, msg.message, isOwn, msg.messageId);

                // 마지막 메시지 타임스탬프 업데이트
                const msgTimestamp = parseInt(msg.timestamp || msg.messageId);
                if (msgTimestamp > lastMessageTimestamp) {
                    setLastMessageTimestamp(msgTimestamp);
                }
            });

            scwin.updateChatMessages();
        }

    } catch (error) {
        scwin.addChatMessage("시스템", "❌ 채팅 기록을 불러오는데 실패했습니다.", false);
    }
};

// 새 메시지 확인
scwin.checkNewMessages = async function() {
    try {
        const response = await fetch('/InsWebApp/ChatMessages.pwkjson', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                "chatVo": {
                    "channelName": currentUser.channelName,
                    "afterTimestamp": lastMessageTimestamp.toString()
                }
            })
        });

        const result = await response.json();

        // WebSquare 응답 처리 - 여러 가능한 구조 대응
        let messages = [];

        if (Array.isArray(result)) {
            messages = result;
        } else if (result && result.elData && Array.isArray(result.elData.chatVo)) {
            // 주요 케이스: elData.chatVo 구조
            messages = result.elData.chatVo;
        } else if (result && Array.isArray(result.chatVo)) {
            messages = result.chatVo;
        } else if (result && result.data && Array.isArray(result.data.chatVo)) {
            messages = result.data.chatVo;
        } else if (result && result.data && Array.isArray(result.data)) {
            messages = result.data;
        } else if (result && typeof result === 'object') {
            // 객체의 모든 값들을 재귀적으로 찾기
            function findArrayInObject(obj, path = '') {
                for (const key in obj) {
                    if (Array.isArray(obj[key])) {
                        return obj[key];
                    } else if (typeof obj[key] === 'object' && obj[key] !== null) {
                        const found = findArrayInObject(obj[key], path ? `${path}.${key}` : key);
                        if (found) return found;
                    }
                }
                return null;
            }

            const foundArray = findArrayInObject(result);
            if (foundArray) {
                messages = foundArray;
            }
        }

        if (messages && messages.length > 0) {
            // 새 메시지들 추가
            messages.forEach(msg => {
                const isOwn = msg.userId === currentUser.userId;
                scwin.addChatMessageToList(msg.userName, msg.message, isOwn, msg.messageId);

                // 마지막 메시지 타임스탬프 업데이트
                const msgTimestamp = parseInt(msg.timestamp || msg.messageId);
                if (msgTimestamp > lastMessageTimestamp) {
                    setLastMessageTimestamp(msgTimestamp);
                }
            });

            scwin.updateChatMessages();
        }

    } catch (error) {
    }
};

// 데이터리스트에 메시지 추가 (내부 함수)
scwin.addChatMessageToList = function(userName, message, isOwn, messageId) {
    const timestamp = new Date().toLocaleTimeString();

    // 데이터 추가
    const rowIndex = dlt_chatMessages.insertRow();
    dlt_chatMessages.setCellData(rowIndex, "messageId", messageId || Date.now().toString());
    dlt_chatMessages.setCellData(rowIndex, "userId", isOwn ? currentUser.userId : "other");
    dlt_chatMessages.setCellData(rowIndex, "userName", userName);
    dlt_chatMessages.setCellData(rowIndex, "message", message);
    dlt_chatMessages.setCellData(rowIndex, "timestamp", timestamp);
    dlt_chatMessages.setCellData(rowIndex, "isOwn", isOwn.toString());
};

// 채팅 메시지 추가 (로컬용 - 시스템 메시지 등)
scwin.addChatMessage = function(userName, message, isOwn) {
    const messageId = Date.now().toString();

    // 내부 함수 사용
    scwin.addChatMessageToList(userName, message, isOwn, messageId);

    // UI 업데이트
    scwin.updateChatMessages();
};

// 채팅 메시지 UI 업데이트 - 강화된 스크롤 버전
scwin.updateChatMessages = function() {
    const chatContainer = document.getElementById("chatMessages");
    if (!chatContainer) {
        return;
    }

    const messages = dlt_chatMessages.getAllJSON();

    chatContainer.innerHTML = "";

    messages.forEach(msg => {
        const messageDiv = document.createElement("div");
        messageDiv.className = `chat-message ${msg.isOwn === 'true' ? 'own' : 'other'}`;
        messageDiv.style.cssText = `
            margin-bottom: 10px;
            padding: 8px 12px;
            border-radius: 8px;
            max-width: 80%;
            word-wrap: break-word;
            ${msg.isOwn === 'true' ? 
                'background: #007bff; color: white; margin-left: auto; text-align: right;' : 
                'background: #f1f1f1; color: black; margin-right: auto; text-align: left;'
            }
        `;

        const headerDiv = document.createElement("div");
        headerDiv.className = "message-header";
        headerDiv.style.cssText = "font-size: 12px; margin-bottom: 4px; opacity: 0.7;";

        const userNameSpan = document.createElement("span");
        userNameSpan.className = "user-name";
        userNameSpan.textContent = msg.userName;
        userNameSpan.style.fontWeight = "bold";

        const timeSpan = document.createElement("span");
        timeSpan.className = "message-time";
        timeSpan.textContent = " " + msg.timestamp;

        headerDiv.appendChild(userNameSpan);
        headerDiv.appendChild(timeSpan);

        const contentDiv = document.createElement("div");
        contentDiv.className = "message-content";
        contentDiv.textContent = msg.message;
        contentDiv.style.cssText = "font-size: 14px; line-height: 1.4;";

        messageDiv.appendChild(headerDiv);
        messageDiv.appendChild(contentDiv);

        chatContainer.appendChild(messageDiv);
    });

    // 먼저 스크롤 강제 활성화
    scwin.forceScrollEnable();

    // 그 다음 여러 방법으로 스크롤을 아래로
    setTimeout(() => {
        // 방법 1: 직접 scrollTop 설정
        chatContainer.scrollTop = chatContainer.scrollHeight;

        // 방법 2: scrollIntoView 사용
        if (chatContainer.lastElementChild) {
            chatContainer.lastElementChild.scrollIntoView({ 
                behavior: 'smooth', 
                block: 'end' 
            });
        }

        // 방법 3: smooth scroll 시도
        try {
            chatContainer.scrollTo({
                top: chatContainer.scrollHeight,
                behavior: 'smooth'
            });
        } catch (e) {
            // smooth scroll 미지원 시 그냥 패스
        }
    }, 100);

    // 한 번 더 확실하게
    setTimeout(() => {
        chatContainer.scrollTop = chatContainer.scrollHeight;
    }, 200);
};

// Enter 키 처리 (모든 키 이벤트용)
scwin.handleChatKeyPress = function(event) {

    // Enter 키 확인 (여러 방법으로)
    const isEnter = (
        event.key === 'Enter' || 
        event.keyCode === 13 || 
        event.which === 13 ||
        event.code === 'Enter'
    );

    if (isEnter && event.type === 'keydown') { // keydown에서만 실행

        event.preventDefault(); // 기본 동작 방지
        event.stopPropagation(); // 이벤트 전파 중지

        // 메시지 전송
        try {
            scwin.sendChatMessage();
        } catch (error) {
        }
        return false; // 추가 안전장치
    }
    return true;
};



// 스크롤 강제 활성화 함수 - 강화된 버전
scwin.forceScrollEnable = function() {
    const chatContainer = document.getElementById("chatMessages");
    if (chatContainer) {

        // 스크롤 속성 강제 적용 - 더 강력하게
        chatContainer.style.setProperty("overflow-y", "scroll", "important");
        chatContainer.style.setProperty("overflow-x", "hidden", "important");
        chatContainer.style.setProperty("height", "100%", "important");
        chatContainer.style.setProperty("max-height", "100%", "important");
        chatContainer.style.setProperty("min-height", "300px", "important");
        chatContainer.style.setProperty("display", "block", "important");
        chatContainer.style.setProperty("position", "relative", "important");

        // 부모 컨테이너들 모두 수정
        let parent = chatContainer.parentElement;
        while (parent && parent.className) {
            if (parent.className.includes("chat-message-container")) {
                parent.style.setProperty("overflow", "hidden", "important");
                parent.style.setProperty("height", "calc(100vh - 140px)", "important");
                parent.style.setProperty("flex", "1", "important");
            } else if (parent.className.includes("chat-section")) {
                parent.style.setProperty("height", "100vh", "important");
                parent.style.setProperty("display", "flex", "important");
                parent.style.setProperty("flex-direction", "column", "important");
                parent.style.setProperty("overflow", "hidden", "important");
            }
            parent = parent.parentElement;
        }

        // 여러번 시도해서 확실하게 스크롤 적용
        for (let i = 0; i < 3; i++) {
            setTimeout(() => {
                chatContainer.scrollTop = chatContainer.scrollHeight;
                // 강제로 스크롤 이벤트 발생
                chatContainer.dispatchEvent(new Event('scroll'));
            }, i * 100);
        }
    } else {
    }
};



// 로딩 표시
scwin.showLoading = function(message) {
    const loadingDiv = document.getElementById("loadingSpinner");
    const loadingText = document.getElementById("loadingText");

    if (loadingText) {
        loadingText.textContent = message || "처리 중...";
    }

    if (loadingDiv) {
        loadingDiv.style.display = "flex";
    }
};

// 로딩 숨기기
scwin.hideLoading = function() {
    const loadingDiv = document.getElementById("loadingSpinner");
    if (loadingDiv) {
        loadingDiv.style.display = "none";
    }
};

// 에러 표시
scwin.showError = function(message) {
    alert("오류: " + message);
};

// 페이지 종료 시 정리
window.addEventListener("beforeunload", function() {
    if (isJoined) {
        scwin.leaveCall();
    }

    // 채팅 폴링 정리
    if (chatPollingInterval) {
        clearInterval(chatPollingInterval);
    }
});
